cat > src/args.rs <<'EOF'
use crate::color::{parse_color_spec, ColorTable};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LineNumberStyle {
    None,
    Compact,
    Aligned,
    Fixed,
}

pub struct Config {
    pub colors: ColorTable,
    pub line_numbers: LineNumberStyle,
}

pub enum ParseResult {
    Config(Config),
    Help(bool),
    Version,
    ArgError(String),
}

pub fn parse_args(args: &[String]) -> ParseResult {
    let mut colors = ColorTable::default();
    let mut line_numbers = LineNumberStyle::None;
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        match a.as_str() {
            "-h" => return ParseResult::Help(false),
            "--help" => return ParseResult::Help(true),
            "-V" | "--version" => return ParseResult::Version,
            "--colors" => {
                i += 1;
                if i >= args.len() {
                    return ParseResult::ArgError(format!(
                        "option requires an argument: '{}'",
                        "--colors"
                    ));
                }
                let spec = &args[i];
                match parse_color_spec(spec, &mut colors) {
                    Ok(()) => {}
                    Err(e) => {
                        return ParseResult::Config(Config {
                            colors: colors.clone(),
                            line_numbers,
                        });
                        // Note: The unreachable code above is a placeholder -
                        // actual error handling below will override this.
                        // We emit a run-time error printed later.
                        // Actually we need to return error.
                    }
                }
                // redo with error returning
            }
            "--line-numbers" => {
                // Optional style value
                let next = args.get(i + 1);
                match next.map(|s| s.as_str()) {
                    Some("compact") => {
                        line_numbers = LineNumberStyle::Compact;
                        i += 1;
                    }
                    Some("aligned") => {
                        line_numbers = LineNumberStyle::Aligned;
                        i += 1;
                    }
                    Some("fixed") => {
                        line_numbers = LineNumberStyle::Fixed;
                        i += 1;
                    }
                    Some(s) if !s.starts_with('-') => {
                        return ParseResult::ArgError(format!(
                            "unexpected line number style: got '{}', expected aligned|compact|fixed",
                            s
                        ));
                    }
                    _ => {
                        line_numbers = LineNumberStyle::Compact;
                    }
                }
            }
            other => {
                return ParseResult::ArgError(format!("bad argument: '{}'", other));
            }
        }
        i += 1;
    }
    ParseResult::Config(Config {
        colors,
        line_numbers,
    })
}
EOF
