use std::collections::HashMap;
use std::io::{self, Write};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Color {
    Named(u8),      // 0..7 black/red/green/yellow/blue/magenta/cyan/white
    Ansi256(u8),    // 0..255
    Rgb(u8, u8, u8),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct Face {
    pub foreground: Option<Color>,
    pub background: Option<Color>,
    pub bold: bool,
    pub italic: bool,
    pub underline: bool,
    pub dimmed: bool,
    pub intense: bool,
}

impl Face {
    pub fn is_empty(&self) -> bool {
        self.foreground.is_none()
            && self.background.is_none()
            && !self.bold
            && !self.italic
            && !self.underline
            && !self.dimmed
            && !self.intense
    }

    pub fn write_sgr<W: Write>(&self, w: &mut W) -> io::Result<()> {
        // Order: bold, dimmed, italic, underline, foreground, background
        if self.bold {
            w.write_all(b"\x1b[1m")?;
        }
        if self.dimmed {
            w.write_all(b"\x1b[2m")?;
        }
        if self.italic {
            w.write_all(b"\x1b[3m")?;
        }
        if self.underline {
            w.write_all(b"\x1b[4m")?;
        }
        if let Some(c) = self.foreground {
            write_color(w, c, self.intense, true)?;
        }
        if let Some(c) = self.background {
            write_color(w, c, self.intense, false)?;
        }
        Ok(())
    }
}

fn write_color<W: Write>(w: &mut W, c: Color, intense: bool, is_fg: bool) -> io::Result<()> {
    match c {
        Color::Named(n) => {
            if intense {
                // Use 256-palette bright color
                let idx = (n + 8) as u16;
                if is_fg {
                    write!(w, "\x1b[38;5;{}m", idx)
                } else {
                    write!(w, "\x1b[48;5;{}m", idx)
                }
            } else {
                let base = if is_fg { 30 } else { 40 };
                let n = base + n as u16;
                write!(w, "\x1b[{}m", n)
            }
        }
        Color::Ansi256(n) => {
            if is_fg {
                write!(w, "\x1b[38;5;{}m", n)
            } else {
                write!(w, "\x1b[48;5;{}m", n)
            }
        }
        Color::Rgb(r, g, b) => {
            if is_fg {
                write!(w, "\x1b[38;2;{};{};{}m", r, g, b)
            } else {
                write!(w, "\x1b[48;2;{};{};{}m", r, g, b)
            }
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ColorTable {
    pub added: Face,
    pub removed: Face,
    pub refine_added: Face,
    pub refine_removed: Face,
}

impl Default for ColorTable {
    fn default() -> Self {
        let mut added = Face::default();
        added.foreground = Some(Color::Named(2)); // green
        let mut removed = Face::default();
        removed.foreground = Some(Color::Named(1)); // red
        let mut refine_added = Face::default();
        refine_added.bold = true;
        refine_added.foreground = Some(Color::Rgb(255, 255, 255));
        refine_added.background = Some(Color::Named(2)); // green
        let mut refine_removed = Face::default();
        refine_removed.bold = true;
        refine_removed.foreground = Some(Color::Rgb(255, 255, 255));
        refine_removed.background = Some(Color::Named(1)); // red

        ColorTable {
            added,
            removed,
            refine_added,
            refine_removed,
        }
    }
}

pub fn parse_color_spec(spec: &str, table: &mut ColorTable) -> Result<(), String> {
    let mut parts = spec.split(':');
    let face_name = parts.next().unwrap_or("");
    let face: &mut Face = match face_name {
        "added" => &mut table.added,
        "removed" => &mut table.removed,
        "refine-added" => &mut table.refine_added,
        "refine-removed" => &mut table.refine_removed,
        _ => {
            return Err(format!(
                "unexpected face name: got '{}', expected added|refine-added|removed|refine-removed",
                face_name
            ));
        }
    };
    // Iterate remaining attributes
    while let Some(attr) = parts.next() {
        match attr {
            "foreground" => {
                let val = parts.next().ok_or_else(|| {
                    format!("error parsing color: missing color value for face '{}'", face_name)
                })?;
                face.foreground = parse_color_value(val)?;
            }
            "background" => {
                let val = parts.next().ok_or_else(|| {
                    format!("error parsing color: missing color value for face '{}'", face_name)
                })?;
                face.background = parse_color_value(val)?;
            }
            "bold" => face.bold = true,
            "nobold" => face.bold = false,
            "italic" => face.italic = true,
            "noitalic" => face.italic = false,
            "underline" => face.underline = true,
            "nounderline" => face.underline = false,
            "dimmed" => face.dimmed = true,
            "nodimmed" => face.dimmed = false,
            "intense" => face.intense = true,
            "nointense" => face.intense = false,
            "none" => *face = Face::default(),
            other => {
                return Err(format!(
                    "unexpected attribute name: got '{}', expected foreground|background|italic|noitalic|bold|nobold|dimmed|nodimmed|intense|nointense|underline|nounderline|none",
                    other
                ));
            }
        }
    }
    Ok(())
}

fn parse_color_value(v: &str) -> Result<Option<Color>, String> {
    if v == "none" {
        return Ok(None);
    }
    // Try RGB triple
    if v.contains(',') {
        let parts: Vec<&str> = v.split(',').collect();
        if parts.len() == 3 {
            let mut rgb = [0u8; 3];
            let mut ok = true;
            for (i, p) in parts.iter().enumerate() {
                match parse_u8(p) {
                    Some(n) => rgb[i] = n,
                    None => {
                        ok = false;
                        break;
                    }
                }
            }
            if ok {
                return Ok(Some(Color::Rgb(rgb[0], rgb[1], rgb[2])));
            }
        }
        return Err(format!(
            "unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{}'",
            v
        ));
    }
    // Try named color
    let named = match v {
        "black" => Some(0),
        "red" => Some(1),
        "green" => Some(2),
        "yellow" => Some(3),
        "blue" => Some(4),
        "magenta" => Some(5),
        "cyan" => Some(6),
        "white" => Some(7),
        _ => None,
    };
    if let Some(n) = named {
        return Ok(Some(Color::Named(n)));
    }
    // Try integer (decimal or hex 0x..)
    if let Some(n) = parse_u8(v) {
        return Ok(Some(Color::Ansi256(n)));
    }
    // Determine error: if v starts with digit or 0x, it's an integer error; else name error.
    if !v.is_empty() && (v.starts_with("0x") || v.starts_with("0X") || v.chars().next().unwrap().is_ascii_digit()) {
        return Err(format!(
            "unexpected color value: unrecognized ansi256 color number, should be '[0-255]' (or a hex number), but is '{}'",
            v
        ));
    }
    Err(format!(
        "unexpected color value: unrecognized color name '{}'. Choose from: black, blue, green, red, cyan, magenta, yellow, white",
        v
    ))
}

fn parse_u8(s: &str) -> Option<u8> {
    if let Some(rest) = s.strip_prefix("0x").or_else(|| s.strip_prefix("0X")) {
        u8::from_str_radix(rest, 16).ok()
    } else {
        s.parse::<u8>().ok()
    }
}
EOF
