        i = eol_end;
    }
    state.flush(data, w)?;
    Ok(())
}

#[derive(Debug, Clone, Copy)]
enum HunkState {
    NotInHunk,
    InHunk,
}

struct BlockEntry {
    // kind: '-' or '+' or '\\' (literal pass-through)
    kind: u8,
    // line bytes in `data`: start..end (exclusive of newline)
    start: usize,
    end: usize,
    has_eol: bool,
    // Leading whitespace end offset relative to start (absolute): up to this byte is leading ws/prefix handling
    content_start: usize,
    // For remove/add: the old/new line number
    lineno: u64,
}

struct State<'a> {
    cfg: &'a Config,
    hunk: HunkState,
    // Current buffered block
    block: Vec<BlockEntry>,
    // Current state in hunk for line numbers
    old_line: u64,
    new_line: u64,
    old_start: u64,
    new_start: u64,
    old_count: u64,
    new_count: u64,
    // Max line width (for compact/aligned/fixed)
    line_width_old: usize,
    line_width_new: usize,
    col_width: usize,
    total_width: usize,
    // Line numbering style
    ln_style: LineNumberStyle,
}

impl<'a> State<'a> {
    fn new(cfg: &'a Config) -> Self {
        State {
            cfg,
            hunk: HunkState::NotInHunk,
            block: Vec::new(),
            old_line: 0,
            new_line: 0,
            old_start: 0,
            new_start: 0,
            old_count: 0,
            new_count: 0,
            line_width_old: 0,
            line_width_new: 0,
            col_width: 0,
            total_width: 0,
            ln_style: cfg.line_numbers,
        }
    }

    fn process_line<W: Write>(
        &mut self,
        data: &[u8],
        line: &[u8],
        start: usize,
        end: usize,
        has_eol: bool,
        w: &mut W,
    ) -> io::Result<()> {
        // First, check for hunk header
        if is_hunk_header(line) {
            // Flush any previous block
            self.flush(data, w)?;
            self.hunk = HunkState::InHunk;
            // Parse the hunk header
            if let Some((os, oc, ns, nc)) = parse_hunk_header(line) {
                self.old_start = os;
                self.old_count = oc;
                self.new_start = ns;
                self.new_count = nc;
                self.old_line = os;
                self.new_line = ns;
                // Compute widths
                let max_old = if oc == 0 { os } else { os + oc - 1 };
                let max_new = if nc == 0 { ns } else { ns + nc - 1 };
                self.line_width_old = width_of(max_old);
                self.line_width_new = width_of(max_new);
                let mut col = self.line_width_old.max(self.line_width_new);
                if self.ln_style == LineNumberStyle::Fixed {
                    col = col.max(3);
                }
                self.col_width = col;
                self.total_width = col * 2 + 1;
            }
            // Print the hunk header line as-is with reset wrappers
            write_plain_line(w, line, has_eol)?;
            return Ok(());
        }

        match self.hunk {
            HunkState::NotInHunk => {
                // Not in hunk; pass-through line
                write_plain_line(w, line, has_eol)?;
                Ok(())
            }
            HunkState::InHunk => self.process_hunk_line(data, line, start, end, has_eol, w),
        }
    }

    fn process_hunk_line<W: Write>(
        &mut self,
        data: &[u8],
        line: &[u8],
        start: usize,
        end: usize,
        has_eol: bool,
        w: &mut W,
    ) -> io::Result<()> {
        if line.is_empty() {
            // Blank line - treat as exiting hunk (strict diff requires " " for empty context line)
            self.flush(data, w)?;
            self.hunk = HunkState::NotInHunk;
            write_plain_line(w, line, has_eol)?;
            return Ok(());
        }
        let first = line[0];
        match first {
            b' ' => {
                // Context line: flush block, print as-is (with possible line numbers)
                self.flush(data, w)?;
                self.write_context_line(w, line, has_eol)?;
                self.old_line += 1;
                self.new_line += 1;
                Ok(())
            }
            b'-' => {
                // Check if block has any '+' already; if so, flush it first
                if self.block.iter().any(|e| e.kind == b'+') {
                    self.flush(data, w)?;
                }
                let content_start = start + 1;
                self.block.push(BlockEntry {
                    kind: b'-',
                    start: start,
                    end: end,
                    has_eol,
                    content_start,
                    lineno: self.old_line,
                });
                self.old_line += 1;
                Ok(())
            }
            b'+' => {
                let content_start = start + 1;
                self.block.push(BlockEntry {
                    kind: b'+',
                    start: start,
                    end: end,
                    has_eol,
                    content_start,
                    lineno: self.new_line,
                });
                self.new_line += 1;
                Ok(())
            }
            b'\\' => {
                // No newline at end of file; keep in block or pass through
                self.block.push(BlockEntry {
                    kind: b'\\',
                    start: start,
                    end: end,
                    has_eol,
                    content_start: start,
                    lineno: 0,
                });
                Ok(())
            }
            _ => {
                // Unknown; end of hunk
                self.flush(data, w)?;
                self.hunk = HunkState::NotInHunk;
                write_plain_line(w, line, has_eol)?;
                Ok(())
            }
        }
    }

    fn flush<W: Write>(&mut self, data: &[u8], w: &mut W) -> io::Result<()> {
        if self.block.is_empty() {
            return Ok(());
        }
        // Collect indices for remove and add entries (in their display order)
        let entries: Vec<BlockEntry> = std::mem::take(&mut self.block);
        // Build remove text/tokens
        let remove_entries: Vec<&BlockEntry> = entries.iter().filter(|e| e.kind == b'-').collect();
        let add_entries: Vec<&BlockEntry> = entries.iter().filter(|e| e.kind == b'+').collect();

        // Compute per-line content starts (skip leading whitespace) and tokens
        // We'll concatenate per-side bytes using the actual data offsets.
        // Each line's tokens start after its leading whitespace; leading ws is part of the prefix.
        //
        // Build byte slices for diff:
        //   remove_bytes: for each removed line, content after leading ws, then '\n' between lines (if has_eol)
        //   add_bytes: similar
        // Use original `data` by constructing separate byte buffers.
        //
        // We keep per-line indexing for rendering.

        let (remove_bytes, remove_line_ranges, remove_prefix_ranges) =
            build_side(&remove_entries, data);
        let (add_bytes, add_line_ranges, add_prefix_ranges) = build_side(&add_entries, data);

        // Tokenize
        let rem_toks = tokenize(&remove_bytes, 0, remove_bytes.len());
        let add_toks = tokenize(&add_bytes, 0, add_bytes.len());

        // Compute diff
        let ops = if !remove_entries.is_empty() && !add_entries.is_empty() {
            lcs_diff(&rem_toks, &add_toks, &remove_bytes, &add_bytes)
        } else {
            // pure add or pure remove; all refine
            let mut ops = Vec::with_capacity(rem_toks.len() + add_toks.len());
            for i in 0..rem_toks.len() {
                ops.push(DiffOp::Remove(i));
            }
            for j in 0..add_toks.len() {
                ops.push(DiffOp::Add(j));
            }
            ops
        };

        // Classify each token as common(true) or unique(false)
        let mut rem_common = vec![false; rem_toks.len()];
        let mut add_common = vec![false; add_toks.len()];
        for op in &ops {
            if let DiffOp::Keep(i, j) = op {
                rem_common[*i] = true;
                add_common[*j] = true;
            }
        }

        // Render entries in their original order
        let is_paired = !remove_entries.is_empty() && !add_entries.is_empty();
        // Whether ops end with refine on each side determines trailing common segment
        // Actually we emit trailing common segment on the LAST line of each side when
        // its last token is refine OR when there's no refine at all? Let's check...
        // From observations:
        //   - Paired, last token is refine -> emit trailing empty common at end of last refine.
        //   - Paired, last token is common -> no empty common needed (ends with common).
        //   - Paired, no refine at all -> no empty common (ends with common, which is all).

        // For unpaired (pure add/remove), no trailing empty common. Example:
        //   -removed -> just refine "removed", no trailing.

        // Render
        let mut rem_idx = 0usize; // index into remove entries
        let mut add_idx = 0usize; // index into add entries
        for e in &entries {
            match e.kind {
                b'-' => {
                    let li = rem_idx;
                    rem_idx += 1;
                    render_line(
                        w,
                        data,
                        e,
                        &remove_bytes,
                        &remove_line_ranges,
                        &remove_prefix_ranges,
                        &rem_toks,
                        &rem_common,
                        li,
                        true,
                        is_paired,
                        &self.cfg.colors,
                        self.cfg.line_numbers,
                        self.col_width,
                        self.line_width_old,
                        self.line_width_new,
                    )?;
                }
                b'+' => {
                    let li = add_idx;
                    add_idx += 1;
                    render_line(
                        w,
                        data,
                        e,
                        &add_bytes,
                        &add_line_ranges,
                        &add_prefix_ranges,
                        &add_toks,
                        &add_common,
                        li,
                        false,
                        is_paired,
                        &self.cfg.colors,
                        self.cfg.line_numbers,
                        self.col_width,
                        self.line_width_old,
                        self.line_width_new,
                    )?;
                }
                b'\\' => {
                    // Pass through
                    let line = &data[e.start..e.end];
                    write_plain_line(w, line, e.has_eol)?;
                }
                _ => {}
            }
        }
        Ok(())
    }

    fn write_context_line<W: Write>(&self, w: &mut W, line: &[u8], has_eol: bool) -> io::Result<()> {
        match self.ln_style {
            LineNumberStyle::None => {
                write_plain_line(w, line, has_eol)?;
            }
            _ => {
                // Write line numbers
                write_context_numbers(
                    w,
                    self.old_line,
                    self.new_line,
                    self.col_width,
                )?;
                if self.ln_style == LineNumberStyle::Aligned {
                    w.write_all(b"\t")?;
                }
                // Then reset + content + reset + newline
                w.write_all(RESET)?;
                w.write_all(line)?;
                w.write_all(RESET)?;
                if has_eol {
                    w.write_all(b"\n")?;
                }
            }
        }
        Ok(())
    }
}

fn write_plain_line<W: Write>(w: &mut W, line: &[u8], has_eol: bool) -> io::Result<()> {
    w.write_all(RESET)?;
    w.write_all(line)?;
    w.write_all(RESET)?;
    if has_eol {
        w.write_all(b"\n")?;
    }
    Ok(())
}

fn is_hunk_header(line: &[u8]) -> bool {
    line.starts_with(b"@@ ") || line.starts_with(b"@@")
        && line.len() > 2
        && false // strict: must be "@@ "
}

fn parse_hunk_header(line: &[u8]) -> Option<(u64, u64, u64, u64)> {
    // Format: @@ -old_start[,old_count] +new_start[,new_count] @@ [optional section heading]
    if !line.starts_with(b"@@ ") {
        return None;
    }
    let s = std::str::from_utf8(line).ok()?;
    let after = s.strip_prefix("@@ ")?;
    // Split off "@@" suffix part
    let idx = after.find(" @@")?;
    let hdr = &after[..idx];
    // hdr = "-old[,oc] +new[,nc]"
    let mut parts = hdr.split_whitespace();
    let old_s = parts.next()?;
    let new_s = parts.next()?;
    let (os, oc) = parse_range(old_s.strip_prefix('-')?)?;
    let (ns, nc) = parse_range(new_s.strip_prefix('+')?)?;
    Some((os, oc, ns, nc))
}

fn parse_range(s: &str) -> Option<(u64, u64)> {
    match s.split_once(',') {
        Some((a, b)) => Some((a.parse().ok()?, b.parse().ok()?)),
        None => Some((s.parse().ok()?, 1)),
    }
}

fn width_of(n: u64) -> usize {
    if n == 0 {
        return 1;
    }
    let mut w = 0usize;
    let mut x = n;
    while x > 0 {
        x /= 10;
        w += 1;
    }
    w
}

fn write_context_numbers<W: Write>(
    w: &mut W,
    old: u64,
    new: u64,
    col_width: usize,
) -> io::Result<()> {
    let total = col_width * 2 + 1;
    if old == new {
        // Show only new, right-aligned in total width
        let s = format!("{:>width$}", new, width = total);
        w.write_all(s.as_bytes())?;
    } else {
        let s = format!(
            "{:>w$} {:>w$}",
            old,
            new,
            w = col_width
        );
        w.write_all(s.as_bytes())?;
    }
    Ok(())
}

// Build byte buffer for a side (a list of entries, all same kind).
// Returns:
//   - the concatenated byte buffer
//   - per-entry (start, end) ranges in the buffer (content after leading ws, up to newline exclusive)
//     plus for each entry a trailing newline byte position (if present, start of newline in buffer; else buffer end)
//   - per-entry prefix_len: length of the "leading whitespace" portion (in the source data, start = entry.start+1, length = leading ws bytes)
fn build_side(
    entries: &[&BlockEntry],
    data: &[u8],
) -> (Vec<u8>, Vec<(usize, usize, usize, bool)>, Vec<(usize, usize)>) {
    // returns (buf, per-entry (content_start_in_buf, content_end_in_buf, newline_pos_in_buf, has_nl), per-entry (leading_ws_start, leading_ws_end) in original data)
    let mut buf = Vec::new();
    let mut ranges = Vec::new();
    let mut prefix_ranges = Vec::new();
    for e in entries {
        // In diff, entry.start points to the prefix char ('-' or '+'), entry.end is end of content (exclusive of newline)
        let content_start_in_data = e.start + 1;
        let content_end_in_data = e.end;
        // Find leading whitespace end
        let mut lws_end = content_start_in_data;
        while lws_end < content_end_in_data {
            let b = data[lws_end];
            if b == b' ' || b == b'\t' {
                lws_end += 1;
            } else {
                break;
            }
        }
        prefix_ranges.push((content_start_in_data, lws_end));
        let buf_content_start = buf.len();
        buf.extend_from_slice(&data[lws_end..content_end_in_data]);
        let buf_content_end = buf.len();
        // Append a newline token if the original has it
        let has_nl = e.has_eol;
        let nl_pos = buf.len();
        if has_nl {
            buf.push(b'\n');
        }
        ranges.push((buf_content_start, buf_content_end, nl_pos, has_nl));
    }
    (buf, ranges, prefix_ranges)
}

// Render a single line (minus/plus).
// This handles:
//   - line number prefix (if enabled)
//   - '-'/'+' prefix plus leading whitespace
//   - segments from token diff (common/refine), split at newlines
//   - trailing empty common segment when needed
fn render_line<W: Write>(
    w: &mut W,
    data: &[u8],
    entry: &BlockEntry,
    side_buf: &[u8],
    line_ranges: &[(usize, usize, usize, bool)],
    prefix_ranges: &[(usize, usize)],
    tokens: &[Token],
    common_mask: &[bool],
    line_idx: usize,
    is_remove: bool,
    is_paired: bool,
    colors: &ColorTable,
    ln_style: LineNumberStyle,
    col_width: usize,
    line_width_old: usize,
    line_width_new: usize,
) -> io::Result<()> {
    // Choose faces
    let (line_face, refine_face, prefix_char) = if is_remove {
        (&colors.removed, &colors.refine_removed, b'-')
    } else {
        (&colors.added, &colors.refine_added, b'+')
    };

    // Line number prefix
    // Always start with RESET before line number (when line_face is non-empty)
    // Actually from observation: for minus/plus, line number prefix is `\e[0m\e[face]<num>\e[0m`
    // This applies ALSO when line_face is empty (empty face still emits \e[0m ... \e[0m wrapper)

    // Determine which tokens fall on this line (between line_ranges[line_idx])
    let (line_buf_start, line_buf_end, nl_pos, has_nl) = line_ranges[line_idx];
    let (_prefix_content_start, lws_end_in_data) = prefix_ranges[line_idx];

    // First: emit line-number prefix segment if line-numbers enabled
    if ln_style != LineNumberStyle::None {
        w.write_all(RESET)?;
        line_face.write_sgr(w)?;
        if is_remove {
            write_minus_numbers(w, entry.lineno, col_width)?;
        } else {
            write_plus_numbers(w, entry.lineno, col_width)?;
        }
        w.write_all(RESET)?;
        if ln_style == LineNumberStyle::Aligned {
            w.write_all(b"\t")?;
        }
    }

    // Emit prefix segment: "\e[0m\e[face]<prefix><leading_ws>\e[0m"
    w.write_all(RESET)?;
    line_face.write_sgr(w)?;
    w.write_all(&[prefix_char])?;
    // Leading whitespace
    w.write_all(&data[entry.start + 1..lws_end_in_data])?;
    w.write_all(RESET)?;

    // Tokens for this line: those that are in [line_buf_start, line_buf_end)
    // or equal to newline at nl_pos (we treat newline as token too)
    // Actually we need to iterate tokens that correspond to this line.
    // Build a list of (token_index, is_common).
    let mut line_segs: Vec<(usize, bool)> = Vec::new();
    for (i, tok) in tokens.iter().enumerate() {
        // Token intersects [line_buf_start, line_buf_end)
        // Skip newline tokens here
        if tok.start >= line_buf_end || tok.end <= line_buf_start {
            continue;
        }
        // Skip newline tokens (they get special handling)
        if tok.start == nl_pos && tok.end == nl_pos + 1 && has_nl {
            continue;
        }
        line_segs.push((i, common_mask[i]));
    }

    // Emit segments with merging (same type adjacent -> one segment).
    // Also: trailing ws-only refine segments on a line get special rendering.
    // First collapse adjacent same-type tokens.
    let mut segs: Vec<(usize, usize, bool)> = Vec::new(); // (start_tok_idx_to_get_start, end_tok_idx (exclusive) for bytes), common
    {
        let mut cur: Option<(usize, usize, bool)> = None; // (start, end_exclusive, common)
        for (ti, common) in &line_segs {
            let t = &tokens[*ti];
            match cur {
                Some((s, _, c)) if c == *common && (_merge_possible(&cur.unwrap(), t)) => {
                    cur = Some((s, t.end, *common));
                }
                _ => {
                    if let Some(seg) = cur.take() {
                        segs.push(seg);
                    }
                    cur = Some((t.start, t.end, *common));
                }
            }
        }
        if let Some(seg) = cur {
            segs.push(seg);
        }
    }

    // Check if the LAST segment on this line is refine AND contains only whitespace
    // If so, render it with the ws-warning face.
    let last_is_refine_ws_only = segs
        .last()
        .map(|(s, e, c)| !*c && is_ws_only(&side_buf[*s..*e]))
        .unwrap_or(false);

    // Render segments
    for (i, seg) in segs.iter().enumerate() {
        let (s, e, common) = *seg;
        let is_last = i == segs.len() - 1;
        w.write_all(RESET)?;
        if common {
            line_face.write_sgr(w)?;
        } else {
            if is_last && last_is_refine_ws_only {
                // Just the special warning bg
                write_ws_warning(w)?;
            } else {
                refine_face.write_sgr(w)?;
            }
        }
        w.write_all(&side_buf[s..e])?;
        w.write_all(RESET)?;
    }

    // Trailing empty common segment:
    // If paired, and the diff contains refine tokens, and the END of overall
    // sequence for this side is refine (or more strictly, last token of this side
    // is refine AND this is the last line of the side)... Let's implement:
    // Emit trailing empty common segment on this line if:
    //   - paired mode
    //   - this line's last rendered segment is refine OR this line has no segments but overall last was refine
    //   - for unpaired (no opposite side): no trailing common
    // Actually, from observations:
    //   Per-line analysis: if the line ends in refine (and paired), emit trailing empty common.
    //   Multi-line: for refine spanning newlines, inner lines don't get trailing common.
    // Wait, let me re-check. For `-line2\n\ ...\n+line3\n+line4\n` (paired, all tokens refine):
    //   - remove: refine `line2`, trailing common empty -> since remove has only 1 line and last is refine
    //   - add line 1: refine `line3` only (no trailing common)
    //   - add line 2: refine `line4`, trailing common empty
    //   So trailing common is only at the very END of the side's last line when last is refine.

    if is_paired {
        // Determine if this is the last line of the side and if the last token on this side is refine
        let is_last_line = line_idx + 1 == line_ranges.len();
        if is_last_line {
            // Find the last NON-newline token in this side
            let last_non_nl_refine = !tokens.is_empty() && {
                let mut refine_last = false;
                for i in (0..tokens.len()).rev() {
                    let t = &tokens[i];
                    if t.end - t.start == 1 && side_buf[t.start] == b'\n' {
                        continue;
                    }
                    refine_last = !common_mask[i];
                    break;
                }
                refine_last
            };
            if last_non_nl_refine {
                w.write_all(RESET)?;
                line_face.write_sgr(w)?;
                w.write_all(RESET)?;
            }
        }
    }

    if entry.has_eol {
        w.write_all(b"\n")?;
    }
    Ok(())
}

fn _merge_possible(_a: &(usize, usize, bool), _b: &Token) -> bool {
    true
}

fn write_minus_numbers<W: Write>(w: &mut W, old: u64, col_width: usize) -> io::Result<()> {
    // Format: {old:>col_width}{spaces:col_width+1}
    let s = format!("{:>w$}", old, w = col_width);
    w.write_all(s.as_bytes())?;
    for _ in 0..(col_width + 1) {
        w.write_all(b" ")?;
    }
    Ok(())
}

fn write_plus_numbers<W: Write>(w: &mut W, new: u64, col_width: usize) -> io::Result<()> {
    // Format: {spaces:col_width+1}{new:>col_width}
    for _ in 0..(col_width + 1) {
        w.write_all(b" ")?;
    }
    let s = format!("{:>w$}", new, w = col_width);
    w.write_all(s.as_bytes())?;
    Ok(())
}
