                self.old_line = os;
                self.new_line = ns;
                let max_old = if oc == 0 { os } else { os + oc - 1 };
                let max_new = if nc == 0 { ns } else { ns + nc - 1 };
                let w_old = width_of(max_old);
                let w_new = width_of(max_new);
                let mut col = w_old.max(w_new);
                if self.ln_style == LineNumberStyle::Fixed {
                    col = col.max(3);
                }
                self.col_width = col;
            }
            write_plain_line(w, line, has_eol)?;
            return Ok(());
        }

        match self.hunk {
            HunkState::NotInHunk => {
                write_plain_line(w, line, has_eol)?;
                Ok(())
            }
            HunkState::InHunk => self.process_hunk_line(data, line, start, end, has_eol, w),
        }
    }

    fn process_hunk_line<W: Write>(
        &mut self,
        data: &[u8],
        line: &[u8],
        start: usize,
        end: usize,
        has_eol: bool,
        w: &mut W,
    ) -> io::Result<()> {
        if line.is_empty() {
            self.flush(data, w)?;
            self.hunk = HunkState::NotInHunk;
            write_plain_line(w, line, has_eol)?;
            return Ok(());
        }
        let first = line[0];
        match first {
            b' ' => {
                self.flush(data, w)?;
                self.write_context_line(w, line, has_eol)?;
                self.old_line += 1;
                self.new_line += 1;
                Ok(())
            }
            b'-' => {
                if self.block.iter().any(|e| e.kind == b'+') {
                    self.flush(data, w)?;
