                self.block.push(BlockEntry {
                    kind: b'-',
                    start,
                    end,
                    has_eol,
                    lineno: self.old_line,
                });
                self.old_line += 1;
                Ok(())
            }
            b'+' => {
                self.block.push(BlockEntry {
                    kind: b'+',
                    start,
                    end,
                    has_eol,
                    lineno: self.new_line,
                });
                self.new_line += 1;
                Ok(())
            }
            b'\\' => {
                self.block.push(BlockEntry {
                    kind: b'\\',
                    start,
                    end,
                    has_eol,
                    lineno: 0,
                });
                Ok(())
            }
            _ => {
                self.flush(data, w)?;
                self.hunk = HunkState::NotInHunk;
                write_plain_line(w, line, has_eol)?;
                Ok(())
            }
        }
