    fn flush<W: Write>(&mut self, data: &[u8], w: &mut W) -> io::Result<()> {
        if self.block.is_empty() {
            return Ok(());
        }
        let entries: Vec<BlockEntry> = std::mem::take(&mut self.block);
        let remove_entries: Vec<&BlockEntry> = entries.iter().filter(|e| e.kind == b'-').collect();
        let add_entries: Vec<&BlockEntry> = entries.iter().filter(|e| e.kind == b'+').collect();

        let (rem_buf, rem_lines, rem_prefix_ranges) = build_side(&remove_entries, data);
        let (add_buf, add_lines, add_prefix_ranges) = build_side(&add_entries, data);

        let rem_toks = tokenize(&rem_buf, 0, rem_buf.len());
        let add_toks = tokenize(&add_buf, 0, add_buf.len());

        let (rem_common, add_common) = if !remove_entries.is_empty() && !add_entries.is_empty() {
            let ops = lcs_diff(&rem_toks, &add_toks, &rem_buf, &add_buf);
            let mut rc = vec![false; rem_toks.len()];
            let mut ac = vec![false; add_toks.len()];
            for op in &ops {
                if let DiffOp::Keep(i, j) = op {
                    rc[*i] = true;
                    ac[*j] = true;
                }
            }
            (rc, ac)
        } else {
            (vec![false; rem_toks.len()], vec![false; add_toks.len()])
        };

        let is_paired = !remove_entries.is_empty() && !add_entries.is_empty();

        let mut rem_idx = 0usize;
        let mut add_idx = 0usize;
        for e in &entries {
            match e.kind {
                b'-' => {
                    let li = rem_idx;
                    rem_idx += 1;
                    render_line(
                        w,
                        data,
                        e,
                        &rem_buf,
                        &rem_lines,
                        &rem_prefix_ranges,
                        &rem_toks,
                        &rem_common,
                        li,
                        true,
                        is_paired,
                        &self.cfg.colors,
                        self.cfg.line_numbers,
                        self.col_width,
                    )?;
                }
                b'+' => {
                    let li = add_idx;
                    add_idx += 1;
                    render_line(
                        w,
                        data,
                        e,
                        &add_buf,
                        &add_lines,
                        &add_prefix_ranges,
                        &add_toks,
                        &add_common,
                        li,
                        false,
                        is_paired,
                        &self.cfg.colors,
                        self.cfg.line_numbers,
                        self.col_width,
                    )?;
                }
                b'\\' => {
                    let line = &data[e.start..e.end];
                    write_plain_line(w, line, e.has_eol)?;
                }
                _ => {}
            }
        }
        Ok(())
    }

    fn write_context_line<W: Write>(&self, w: &mut W, line: &[u8], has_eol: bool) -> io::Result<()> {
        match self.ln_style {
            LineNumberStyle::None => {
                write_plain_line(w, line, has_eol)?;
            }
            _ => {
                write_context_numbers(w, self.old_line, self.new_line, self.col_width)?;
                if self.ln_style == LineNumberStyle::Aligned {
                    w.write_all(b"\t")?;
                }
                w.write_all(RESET)?;
                w.write_all(line)?;
                w.write_all(RESET)?;
                if has_eol {
                    w.write_all(b"\n")?;
                }
            }
        }
        Ok(())
    }
}

fn write_plain_line<W: Write>(w: &mut W, line: &[u8], has_eol: bool) -> io::Result<()> {
    w.write_all(RESET)?;
    w.write_all(line)?;
    w.write_all(RESET)?;
    if has_eol {
        w.write_all(b"\n")?;
    }
    Ok(())
}

fn is_hunk_header(line: &[u8]) -> bool {
    line.starts_with(b"@@ ")
}

fn parse_hunk_header(line: &[u8]) -> Option<(u64, u64, u64, u64)> {
    if !line.starts_with(b"@@ ") {
        return None;
    }
    let s = std::str::from_utf8(line).ok()?;
    let after = s.strip_prefix("@@ ")?;
    let idx = after.find(" @@")?;
    let hdr = &after[..idx];
    let mut parts = hdr.split_whitespace();
    let old_s = parts.next()?;
    let new_s = parts.next()?;
    let (os, oc) = parse_range(old_s.strip_prefix('-')?)?;
    let (ns, nc) = parse_range(new_s.strip_prefix('+')?)?;
    Some((os, oc, ns, nc))
}

fn parse_range(s: &str) -> Option<(u64, u64)> {
    match s.split_once(',') {
        Some((a, b)) => Some((a.parse().ok()?, b.parse().ok()?)),
        None => Some((s.parse().ok()?, 1)),
    }
}

fn width_of(n: u64) -> usize {
    if n == 0 {
        return 1;
    }
    let mut w = 0usize;
    let mut x = n;
    while x > 0 {
        x /= 10;
        w += 1;
    }
    w
}

fn write_context_numbers<W: Write>(
    w: &mut W,
    old: u64,
    new: u64,
    col_width: usize,
) -> io::Result<()> {
    let total = col_width * 2 + 1;
    if old == new {
        let s = format!("{:>width$}", new, width = total);
        w.write_all(s.as_bytes())?;
    } else {
        let s = format!("{:>w$} {:>w$}", old, new, w = col_width);
        w.write_all(s.as_bytes())?;
    }
    Ok(())
}

// For each entry on a side, returns:
//   - concatenated bytes buffer (content after leading ws, plus newline bytes between lines)
//   - per-line: (content_start_in_buf, content_end_in_buf, nl_pos_in_buf, has_nl, token_idx_of_newline)
//   - per-entry: (leading_ws_start_in_data, leading_ws_end_in_data) - the leading whitespace range
fn build_side(
    entries: &[&BlockEntry],
    data: &[u8],
) -> (
    Vec<u8>,
    Vec<(usize, usize, usize, bool)>,
    Vec<(usize, usize)>,
) {
    let mut buf = Vec::new();
    let mut lines = Vec::new();
    let mut prefixes = Vec::new();
    for e in entries {
        let content_start_in_data = e.start + 1;
        let content_end_in_data = e.end;
        let mut lws_end = content_start_in_data;
        while lws_end < content_end_in_data {
            let b = data[lws_end];
            if b == b' ' || b == b'\t' {
                lws_end += 1;
            } else {
                break;
            }
        }
        prefixes.push((content_start_in_data, lws_end));
        let buf_content_start = buf.len();
        buf.extend_from_slice(&data[lws_end..content_end_in_data]);
        let buf_content_end = buf.len();
        let nl_pos = buf.len();
        if e.has_eol {
            buf.push(b'\n');
        }
        lines.push((buf_content_start, buf_content_end, nl_pos, e.has_eol));
    }
    (buf, lines, prefixes)
}

fn render_line<W: Write>(
    w: &mut W,
    data: &[u8],
    entry: &BlockEntry,
    side_buf: &[u8],
    lines: &[(usize, usize, usize, bool)],
    prefixes: &[(usize, usize)],
    tokens: &[Token],
    common: &[bool],
    line_idx: usize,
    is_remove: bool,
    is_paired: bool,
    colors: &ColorTable,
    ln_style: LineNumberStyle,
    col_width: usize,
) -> io::Result<()> {
    let (line_face, refine_face, prefix_char) = if is_remove {
        (&colors.removed, &colors.refine_removed, b'-')
    } else {
        (&colors.added, &colors.refine_added, b'+')
    };

    let (content_start, content_end, _nl_pos, has_nl) = lines[line_idx];
    let (_content_start_data, lws_end_in_data) = prefixes[line_idx];

    // Line number prefix
    if ln_style != LineNumberStyle::None {
        w.write_all(RESET)?;
        line_face.write_sgr(w)?;
        if is_remove {
            write_minus_numbers(w, entry.lineno, col_width)?;
        } else {
            write_plus_numbers(w, entry.lineno, col_width)?;
        }
        w.write_all(RESET)?;
        if ln_style == LineNumberStyle::Aligned {
            w.write_all(b"\t")?;
        }
    }

    // Prefix segment
    w.write_all(RESET)?;
    line_face.write_sgr(w)?;
    w.write_all(&[prefix_char])?;
    w.write_all(&data[entry.start + 1..lws_end_in_data])?;
    w.write_all(RESET)?;

    // Find tokens on this line (content only, not newline terminator)
    // Content tokens have start >= content_start and end <= content_end
    let mut line_tokens: Vec<usize> = Vec::new();
    for (ti, t) in tokens.iter().enumerate() {
        if t.start >= content_end {
            break;
        }
        if t.end <= content_start {
            continue;
        }
        line_tokens.push(ti);
    }

    // Group into segments (same-type runs)
    let mut segs: Vec<(usize, usize, bool)> = Vec::new(); // (byte_start, byte_end, is_common)
    let mut cur: Option<(usize, usize, bool)> = None;
    for ti in &line_tokens {
        let t = &tokens[*ti];
        let is_common = common[*ti];
        match cur {
            Some((s, _, c)) if c == is_common => {
                cur = Some((s, t.end, is_common));
            }
            _ => {
                if let Some(seg) = cur.take() {
                    segs.push(seg);
                }
                cur = Some((t.start, t.end, is_common));
            }
        }
    }
    if let Some(seg) = cur {
        segs.push(seg);
    }

    // Check: last segment is refine AND is whitespace-only
    let last_is_refine_ws = segs
        .last()
        .map(|(s, e, c)| !*c && is_ws_only(&side_buf[*s..*e]))
        .unwrap_or(false);

    // Emit segments
    for (i, (s, e, common_seg)) in segs.iter().enumerate() {
        let is_last = i == segs.len() - 1;
        w.write_all(RESET)?;
        if *common_seg {
            line_face.write_sgr(w)?;
        } else if is_last && last_is_refine_ws {
            write_ws_warning(w)?;
        } else {
            refine_face.write_sgr(w)?;
        }
        w.write_all(&side_buf[*s..*e])?;
        w.write_all(RESET)?;
    }

    // Trailing common segment:
    // Determine if a refine segment on this line ENDS at the end of this line
    // (i.e., doesn't continue to next line). If so, emit trailing common.
    // A refine continues to next line iff:
    //   - There is a next line
    //   - The terminating newline token exists and is REFINE (same type)
    //     AND next line's first token is also refine (or... simpler rule)
    // Actually, the simpler rule: check the next token AFTER last line token.
    // If next token exists and is refine (same type as last seg) and is on a subsequent line, continues.
    // If next token is common (or non-existent), the refine segment ends here.
    if is_paired && !segs.is_empty() {
        let (_, _, last_common) = segs[segs.len() - 1];
        if !last_common {
            // The last displayed token on this line
            let last_line_tok = *line_tokens.last().unwrap();
            // Check next token
            let next_ti = last_line_tok + 1;
            let refine_continues = if next_ti < tokens.len() {
                // Next token is common or refine?
                // If next is common, refine ends here, emit trailing common.
                // If next is refine, refine CONTINUES. Don't emit trailing common.
                !common[next_ti]
            } else {
                false // no more tokens, refine ends
            };
            if !refine_continues {
                w.write_all(RESET)?;
                line_face.write_sgr(w)?;
                w.write_all(RESET)?;
            }
        }
    }

    if entry.has_eol {
        w.write_all(b"\n")?;
    }
    Ok(())
}

fn write_minus_numbers<W: Write>(w: &mut W, old: u64, col_width: usize) -> io::Result<()> {
    let s = format!("{:>w$}", old, w = col_width);
    w.write_all(s.as_bytes())?;
    for _ in 0..(col_width + 1) {
        w.write_all(b" ")?;
    }
    Ok(())
}

fn write_plus_numbers<W: Write>(w: &mut W, new: u64, col_width: usize) -> io::Result<()> {
    for _ in 0..(col_width + 1) {
        w.write_all(b" ")?;
    }
    let s = format!("{:>w$}", new, w = col_width);
    w.write_all(s.as_bytes())?;
    Ok(())
}
