            // The last displayed token on this line
            let last_line_tok = *line_tokens.last().unwrap();
            // Check next token
            let next_ti = last_line_tok + 1;
            let refine_continues = if next_ti < tokens.len() {
                // Next token is common or refine?
                // If next is common, refine ends here, emit trailing common.
                // If next is refine, refine CONTINUES. Don't emit trailing common.
                !common[next_ti]
            } else {
                false // no more tokens, refine ends
            };
            if !refine_continues {
                w.write_all(RESET)?;
                line_face.write_sgr(w)?;
                w.write_all(RESET)?;
            }
        }
    }

    if entry.has_eol {
        w.write_all(b"\n")?;
    }
    Ok(())
}

fn write_minus_numbers<W: Write>(w: &mut W, old: u64, col_width: usize) -> io::Result<()> {
    let s = format!("{:>w$}", old, w = col_width);
    w.write_all(s.as_bytes())?;
    for _ in 0..(col_width + 1) {
        w.write_all(b" ")?;
    }
    Ok(())
}

fn write_plus_numbers<W: Write>(w: &mut W, new: u64, col_width: usize) -> io::Result<()> {
    for _ in 0..(col_width + 1) {
        w.write_all(b" ")?;
    }
    let s = format!("{:>w$}", new, w = col_width);
    w.write_all(s.as_bytes())?;
    Ok(())
}
