use crate::tokenize::{tokens_equal, Token};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DiffOp {
    Keep(usize, usize),
    Remove(usize),
    Add(usize),
}

pub fn lcs_diff(
    a: &[Token],
    b: &[Token],
    data_a: &[u8],
    data_b: &[u8],
) -> Vec<DiffOp> {
    let n = a.len();
    let m = b.len();

    if n * m > 1_000_000 {
        let mut out = Vec::with_capacity(n + m);
        for i in 0..n {
            out.push(DiffOp::Remove(i));
        }
        for j in 0..m {
            out.push(DiffOp::Add(j));
        }
        return out;
    }

    let mut dp = vec![0u32; (n + 1) * (m + 1)];
    let idx = |i: usize, j: usize| i * (m + 1) + j;
    for i in 0..n {
        for j in 0..m {
            let same = tokens_equal(&a[i], &b[j], data_a, data_b);
            let v = if same {
                dp[idx(i, j)] + 1
            } else {
                dp[idx(i, j + 1)].max(dp[idx(i + 1, j)])
            };
            dp[idx(i + 1, j + 1)] = v;
        }
    }
    let mut ops: Vec<DiffOp> = Vec::new();
    let mut i = n;
    let mut j = m;
    while i > 0 && j > 0 {
        let same = tokens_equal(&a[i - 1], &b[j - 1], data_a, data_b);
        // Strictly greater check: only keep when match is "essential"
        let keep_val = if same { dp[idx(i - 1, j - 1)] + 1 } else { 0 };
        let up = dp[idx(i - 1, j)];
        let left = dp[idx(i, j - 1)];
        if same && keep_val > up && keep_val > left {
            ops.push(DiffOp::Keep(i - 1, j - 1));
            i -= 1;
            j -= 1;
        } else if up > left {
            ops.push(DiffOp::Remove(i - 1));
            i -= 1;
        } else if left > up {
            ops.push(DiffOp::Add(j - 1));
            j -= 1;
        } else {
            // Tied up == left
            if same && keep_val > up {
                ops.push(DiffOp::Keep(i - 1, j - 1));
                i -= 1;
                j -= 1;
            } else {
                ops.push(DiffOp::Add(j - 1));
                j -= 1;
            }
        }
    }
    while i > 0 {
        ops.push(DiffOp::Remove(i - 1));
        i -= 1;
    }
    while j > 0 {
        ops.push(DiffOp::Add(j - 1));
        j -= 1;
    }
    ops.reverse();
    ops
}
