new_render = '''fn render_line<W: Write>(
    w: &mut W,
    data: &[u8],
    entry: &BlockEntry,
    side_buf: &[u8],
    lines: &[(usize, usize, usize, bool)],
    prefixes: &[(usize, usize)],
    tokens: &[Token],
    common: &[bool],
    line_idx: usize,
    is_remove: bool,
    paired_with_content: bool,
    is_content_line: bool,
    colors: &ColorTable,
    ln_style: LineNumberStyle,
    col_width: usize,
) -> io::Result<()> {
    let (line_face, refine_face, prefix_char) = if is_remove {
        (&colors.removed, &colors.refine_removed, b'-')
    } else {
        (&colors.added, &colors.refine_added, b'+')
    };

    let (content_start, content_end, _nl_pos, _has_nl) = lines[line_idx];
    let (_content_start_data, lws_end_in_data) = prefixes[line_idx];

    // Line number prefix
    if ln_style != LineNumberStyle::None {
        w.write_all(RESET)?;
        line_face.write_sgr(w)?;
        if is_remove {
            write_minus_numbers(w, entry.lineno, col_width)?;
        } else {
            write_plus_numbers(w, entry.lineno, col_width)?;
        }
        w.write_all(RESET)?;
        if ln_style == LineNumberStyle::Aligned {
            w.write_all(b"\\t")?;
        }
    }

    // Prefix segment
    w.write_all(RESET)?;
    line_face.write_sgr(w)?;
    w.write_all(&[prefix_char])?;
    w.write_all(&data[entry.start + 1..lws_end_in_data])?;
    w.write_all(RESET)?;

    if !is_content_line {
        // Render entire content with ws-warning face
        w.write_all(RESET)?;
        write_ws_warning(w)?;
        w.write_all(&data[lws_end_in_data..content_end - content_start + lws_end_in_data.saturating_sub(0)])?;
        // Actually we want bytes from lws_end to actual end-of-content on original line
        // Simpler: the content (after leading ws skipping, which is NOT done for ws-only lines) is everything from entry.start+1 to entry.end, minus the prefix char
        // For ws-only lines, lws_end_in_data == entry.start + 1 (no stripping) — wait actually we may have stripped. Let me use data directly.
        // Correction: for ws-only lines, has_nonws is false in build_side, so lws_end = content_start_in_data (no stripping).
        // So data[entry.start+1..entry.end] is the full content, and prefix already wrote data[entry.start+1..lws_end] which equals empty.
        w.write_all(RESET)?;
        if entry.has_eol {
            w.write_all(b"\\n")?;
        }
        return Ok(());
    }

    // Find content tokens on this line
    let mut line_tokens: Vec<usize> = Vec::new();
    for (ti, t) in tokens.iter().enumerate() {
        if t.start >= content_end {
            break;
        }
        if t.end <= content_start {
            continue;
        }
        line_tokens.push(ti);
    }

    // Group into segments
    let mut segs: Vec<(usize, usize, bool)> = Vec::new();
    let mut cur: Option<(usize, usize, bool)> = None;
    for ti in &line_tokens {
        let t = &tokens[*ti];
        let is_common = common[*ti];
        match cur {
            Some((s, _, c)) if c == is_common => {
                cur = Some((s, t.end, is_common));
            }
            _ => {
                if let Some(seg) = cur.take() {
                    segs.push(seg);
                }
                cur = Some((t.start, t.end, is_common));
            }
        }
    }
    if let Some(seg) = cur {
        segs.push(seg);
    }

    // Check: last segment is refine AND ws-only (trailing whitespace refine)
    let last_is_refine_ws = segs
        .last()
        .map(|(s, e, c)| !*c && is_ws_only(&side_buf[*s..*e]))
        .unwrap_or(false);

    // Render segments
    for (i, (s, e, common_seg)) in segs.iter().enumerate() {
        let is_last = i == segs.len() - 1;
        w.write_all(RESET)?;
        if *common_seg {
            line_face.write_sgr(w)?;
        } else if is_last && last_is_refine_ws {
            write_ws_warning(w)?;
        } else {
            refine_face.write_sgr(w)?;
        }
        w.write_all(&side_buf[*s..*e])?;
        w.write_all(RESET)?;
    }

    // Trailing common: paired_with_content AND last segment is refine (normal or ws-warning)
    if paired_with_content && !segs.is_empty() {
        let (_, _, last_common) = segs[segs.len() - 1];
        if !last_common {
            w.write_all(RESET)?;
            line_face.write_sgr(w)?;
            w.write_all(RESET)?;
        }
    }

    if entry.has_eol {
        w.write_all(b"\\n")?;
    }
    Ok(())
}

'''

