use crate::tokenize::{tokens_equal, Token};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DiffOp {
    Keep(usize, usize),
    Remove(usize),
    Add(usize),
}

pub fn lcs_diff(
    a: &[Token],
    b: &[Token],
    data_a: &[u8],
    data_b: &[u8],
) -> Vec<DiffOp> {
    let n = a.len();
    let m = b.len();

    // Common prefix
    let mut p = 0;
    while p < n && p < m && tokens_equal(&a[p], &b[p], data_a, data_b) {
        p += 1;
    }
    // Common suffix
    let mut s = 0;
    while s < n - p && s < m - p && tokens_equal(&a[n - 1 - s], &b[m - 1 - s], data_a, data_b) {
        s += 1;
    }

    let mid_a = &a[p..n - s];
    let mid_b = &b[p..m - s];

    let mut ops = Vec::new();
    // Prefix Keeps
    for k in 0..p {
        ops.push(DiffOp::Keep(k, k));
    }
    // Middle LCS
    let middle_ops = lcs_middle(mid_a, mid_b, data_a, data_b, p, p);
    ops.extend(middle_ops);
    // Suffix Keeps
    for k in 0..s {
        ops.push(DiffOp::Keep(n - s + k, m - s + k));
    }
    ops
}

fn lcs_middle(
    a: &[Token],
    b: &[Token],
    data_a: &[u8],
    data_b: &[u8],
    base_a: usize,
    base_b: usize,
) -> Vec<DiffOp> {
    let n = a.len();
    let m = b.len();
    if n == 0 {
        return (0..m).map(|j| DiffOp::Add(base_b + j)).collect();
    }
    if m == 0 {
        return (0..n).map(|i| DiffOp::Remove(base_a + i)).collect();
    }

    if n * m > 1_000_000 {
        let mut out = Vec::with_capacity(n + m);
        for i in 0..n {
            out.push(DiffOp::Remove(base_a + i));
        }
        for j in 0..m {
            out.push(DiffOp::Add(base_b + j));
        }
        return out;
    }

    let mut dp = vec![0u32; (n + 1) * (m + 1)];
    let idx = |i: usize, j: usize| i * (m + 1) + j;
    for i in 0..n {
        for j in 0..m {
            let same = tokens_equal(&a[i], &b[j], data_a, data_b);
            let v = if same {
                dp[idx(i, j)] + 1
            } else {
                dp[idx(i, j + 1)].max(dp[idx(i + 1, j)])
            };
            dp[idx(i + 1, j + 1)] = v;
        }
