# Modify flush to pass LCS ops (or compute opposite-line-content map)
# I'll compute a map: for each line's term_nl token index on this side, 
# which line on the other side has the corresponding (matched) \n

# Actually simpler: for a line's term \n (token index in this side's tokens),
# look up if it's common. If common, find the matching token in OPS (which has Keep(i, j) for pairs).
# Then find which line on other side that j belongs to.

# Let me rewrite the flush section.

# Find the flush function start and end
start = c.find('    fn flush<W: Write>(&mut self, data: &[u8], w: &mut W) -> io::Result<()> {')
end = c.find('    fn write_context_line<W')

new_flush = '''    fn flush<W: Write>(&mut self, data: &[u8], w: &mut W) -> io::Result<()> {
        if self.block.is_empty() {
            return Ok(());
        }
        let entries: Vec<BlockEntry> = std::mem::take(&mut self.block);
        let block_old_start = self.block_old_start;
        let block_new_start = self.block_new_start;
        let mut context_old_line = block_old_start;
        let mut context_new_line = block_new_start;

        let remove_entries: Vec<&BlockEntry> = entries.iter().filter(|e| e.kind == b'-').collect();
        let add_entries: Vec<&BlockEntry> = entries.iter().filter(|e| e.kind == b'+').collect();

        let (rem_buf, rem_lines, rem_prefix_ranges) = build_side(&remove_entries, data);
        let (add_buf, add_lines, add_prefix_ranges) = build_side(&add_entries, data);

        let rem_toks = tokenize(&rem_buf, 0, rem_buf.len());
        let add_toks = tokenize(&add_buf, 0, add_buf.len());

        // Determine for each line if it's a "content line" (has non-ws content)
        let rem_is_content: Vec<bool> = remove_entries.iter().map(|e| entry_is_content(e, data)).collect();
        let add_is_content: Vec<bool> = add_entries.iter().map(|e| entry_is_content(e, data)).collect();

        let is_paired = !remove_entries.is_empty() && !add_entries.is_empty();

        // Compute common masks and the mapping of matched token indices
        let (rem_common, add_common, rem_nl_to_add_line, add_nl_to_rem_line) = if is_paired {
            let ops = lcs_diff(&rem_toks, &add_toks, &rem_buf, &add_buf);
            let mut rc = vec![false; rem_toks.len()];
            let mut ac = vec![false; add_toks.len()];
            // Map remove token index -> matched add token index
            let mut rem_to_add: std::collections::HashMap<usize, usize> = std::collections::HashMap::new();
            for op in &ops {
                if let DiffOp::Keep(i, j) = op {
                    rc[*i] = true;
                    ac[*j] = true;
                    rem_to_add.insert(*i, *j);
                }
            }
            // Build: rem_nl_to_add_line: for each rem line index, which add line index its term \\n corresponds to.
            let add_line_of_tok: Vec<usize> = {
                let mut map = Vec::new();
                // For each add line, mark token range.
                for (li, (_cs, _ce, nl_pos, has_nl)) in add_lines.iter().enumerate() {
                    // Find token at nl_pos (the terminating newline)
                    let _ = (nl_pos, has_nl);
                    let _ = li;
                }
                // Build by iterating tokens and lines together.
                let mut m = vec![0usize; add_toks.len()];
                let mut line_i = 0usize;
                for (ti, t) in add_toks.iter().enumerate() {
                    while line_i + 1 < add_lines.len() && t.start >= add_lines[line_i + 1].0 {
                        line_i += 1;
                    }
                    m[ti] = line_i;
                }
                m
            };
            let rem_line_of_tok: Vec<usize> = {
                let mut m = vec![0usize; rem_toks.len()];
                let mut line_i = 0usize;
                for (ti, t) in rem_toks.iter().enumerate() {
                    while line_i + 1 < rem_lines.len() && t.start >= rem_lines[line_i + 1].0 {
                        line_i += 1;
                    }
                    m[ti] = line_i;
                }
                m
            };
            let mut rem_nl_to_add_line: std::collections::HashMap<usize, usize> =
                std::collections::HashMap::new();
            let mut add_nl_to_rem_line: std::collections::HashMap<usize, usize> =
                std::collections::HashMap::new();
            for (&ri, &aj) in rem_to_add.iter() {
                let rt = &rem_toks[ri];
                let at = &add_toks[aj];
                // Only for newline tokens
                if rt.end - rt.start == 1 && rem_buf[rt.start] == b'\\n'
                    && at.end - at.start == 1 && add_buf[at.start] == b'\\n' {
                    let rline = rem_line_of_tok[ri];
                    let aline = add_line_of_tok[aj];
                    rem_nl_to_add_line.insert(rline, aline);
                    add_nl_to_rem_line.insert(aline, rline);
                }
            }
            (rc, ac, rem_nl_to_add_line, add_nl_to_rem_line)
        } else {
            (
                vec![false; rem_toks.len()],
                vec![false; add_toks.len()],
                std::collections::HashMap::new(),
                std::collections::HashMap::new(),
            )
        };

        let mut rem_idx = 0usize;
        let mut add_idx = 0usize;
        for e in &entries {
            match e.kind {
                b'-' => {
                    let li = rem_idx;
                    rem_idx += 1;
                    context_old_line += 1;
                    // Determine if paired_with_content based on nl mapping
                    let paired_with_content = rem_nl_to_add_line
                        .get(&li)
                        .map(|&aline| add_is_content.get(aline).copied().unwrap_or(false))
                        .unwrap_or(false);
                    render_line(
                        w,
                        data,
                        e,
                        &rem_buf,
                        &rem_lines,
                        &rem_prefix_ranges,
                        &rem_toks,
                        &rem_common,
                        li,
                        true,
                        paired_with_content,
                        rem_is_content[li],
                        &self.cfg.colors,
                        self.cfg.line_numbers,
                        self.col_width,
                    )?;
                }
                b'+' => {
                    let li = add_idx;
                    add_idx += 1;
                    context_new_line += 1;
                    let paired_with_content = add_nl_to_rem_line
                        .get(&li)
                        .map(|&rline| rem_is_content.get(rline).copied().unwrap_or(false))
                        .unwrap_or(false);
                    render_line(
                        w,
                        data,
                        e,
                        &add_buf,
                        &add_lines,
                        &add_prefix_ranges,
                        &add_toks,
                        &add_common,
                        li,
                        false,
                        paired_with_content,
                        add_is_content[li],
                        &self.cfg.colors,
                        self.cfg.line_numbers,
                        self.col_width,
                    )?;
                }
                b'\\\\' => {
                    let line = &data[e.start..e.end];
                    write_plain_line(w, line, e.has_eol)?;
                }
                b' ' => {
                    let line = &data[e.start..e.end];
                    write_context_line_at(
                        w,
                        line,
                        e.has_eol,
                        self.cfg.line_numbers,
                        self.col_width,
                        context_old_line,
                        context_new_line,
                    )?;
                    context_old_line += 1;
                    context_new_line += 1;
                }
                _ => {}
            }
        }
        Ok(())
    }'''

